<?php
require __DIR__.'/app-bootstrap.php';
$u=require_admin();require $privateRootPath.'/src/admin_payout_layout.php';
$month=(string)($_GET['month']??date('Y-m',strtotime('first day of last month')));if(!preg_match('/^\d{4}-\d{2}$/',$month))$month=date('Y-m',strtotime('first day of last month'));$start=$month.'-01';$end=date('Y-m-t',strtotime($start));
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$userId=(int)($_POST['user_id']??0);$start=(string)($_POST['period_start']??'');$end=(string)($_POST['period_end']??'');$st=$pdo->prepare('SELECT id,display_name,email,paypal_email FROM users WHERE id=? AND is_artist=1');$st->execute([$userId]);$recipient=$st->fetch();if(!$recipient)throw new RuntimeException('Artist user not found.');if(!filter_var((string)$recipient['paypal_email'],FILTER_VALIDATE_EMAIL))throw new RuntimeException('This user has not supplied a valid PayPal email address.');$due=payout_items_for_user($userId,$start,$end);if((int)$due['payout_pence']<1||empty($due['items']))throw new RuntimeException('There is no unpaid balance for this user in the selected period.');$artistId=(int)$due['items'][0]['artist_id'];$artistNames=array_values(array_unique(array_map(static fn(array $item):string=>(string)$item['artist_name'],$due['items'])));$pdo->beginTransaction();$pdo->prepare('INSERT INTO artist_payouts(artist_id,user_id,period_start,period_end,gross_pence,host_fee_pence,payout_pence,currency,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$artistId,$userId,$start,$end,$due['gross_pence'],$due['host_fee_pence'],$due['payout_pence'],paypal_config()['currency'],'paid',(int)$u['id']]);$payoutId=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO artist_payout_items(payout_id,order_item_id,artist_id,gross_pence,host_fee_pence,artist_share_pence) VALUES(?,?,?,?,?,?)');foreach($due['items'] as $item)$ins->execute([$payoutId,$item['order_item_id'],$item['artist_id'],$item['gross_pence'],$item['host_fee_pence'],$item['artist_share_pence']]);$pdo->commit();try{send_artist_payout_reconciliation((string)$recipient['paypal_email'],(string)$recipient['display_name'].' ('.implode(' x ',$artistNames).')',$start,$end,(int)$due['payout_pence'],$due['items'],'paid');}catch(Throwable $ignored){error_log('Artist payout confirmation email failed: '.$ignored->getMessage());}admin_payout_redirect('admin-payout-reports.php?month='.rawurlencode(substr($start,0,7)),'Payout marked as paid for '.(string)$recipient['display_name'].'.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['admin_flash']=['message'=>$e->getMessage(),'error'=>true];admin_payout_redirect('admin-payout-reports.php?month='.rawurlencode($month));}}
$users=$pdo->query("SELECT u.id,u.display_name,u.email,u.paypal_email,GROUP_CONCAT(a.name ORDER BY a.name SEPARATOR ', ') artist_names FROM users u JOIN artists a ON a.owner_user_id=u.id WHERE u.is_artist=1 GROUP BY u.id,u.display_name,u.email,u.paypal_email ORDER BY u.display_name,u.id")->fetchAll();admin_payout_layout_start('reports');admin_payout_flash();
?>
<style>.payout-user-table{overflow-x:auto}.payout-user-table .admin-row{min-width:1180px;grid-template-columns:minmax(180px,1.2fr) minmax(180px,1.3fr) minmax(220px,1.5fr) 100px 100px 120px 150px;gap:16px;align-items:center}.payout-user-table .admin-row>span{min-width:0;overflow-wrap:anywhere}.payout-user-table .admin-row>span:nth-child(n+3),.payout-user-table .admin-row.user-admin-head strong:nth-child(n+3){text-align:right}.payout-user-table .admin-row form{display:flex;justify-content:flex-end}</style>
<div class="section-title"><div><span class="kicker">ARTIST ACCOUNTING</span><h1>Payout Reports</h1></div><span><?=e($start)?> to <?=e($end)?></span></div><p class="panel muted">Payouts are grouped by user. All aliases owned by the same user are combined into one amount and paid to that user’s single PayPal account. The sale allocation remains recorded per artist and track to prevent duplicate payment.</p><form method="get" class="panel admin-compact-form cols"><label>Calendar month<select name="month" onchange="this.form.submit()"><?php for($y=(int)date('Y');$y>=(int)date('Y')-3;$y--):?><?php for($m=1;$m<=12;$m++):$value=sprintf('%04d-%02d',$y,$m);?><option value="<?=$value?>" <?=$value===$month?'selected':''?>><?=date('F Y',strtotime($value.'-01'))?></option><?php endfor;?><?php endfor;?></select><small>Current year and previous three years.</small></label></form><section class="panel admin-list-panel"><div class="admin-section-head"><h2>Payouts by user</h2><span><?=e($start)?> to <?=e($end)?></span></div><div class="admin-table payout-table payout-user-table"><div class="admin-row user-admin-head"><strong>User</strong><strong>Artist aliases</strong><strong>PayPal address</strong><strong>Gross</strong><strong>Host fee</strong><strong>Amount to pay</strong><strong>Action</strong></div><?php foreach($users as $recipient):$due=payout_items_for_user((int)$recipient['id'],$start,$end);?><div class="admin-row"><span><strong><?=e($recipient['display_name'])?></strong><small><?=e($recipient['email'])?></small></span><span><?=e($recipient['artist_names'])?></span><span><?=!empty($recipient['paypal_email'])?e($recipient['paypal_email']):'<span class="muted">Not supplied</span>'?></span><span><?=money((int)$due['gross_pence'])?></span><span><?=money((int)$due['host_fee_pence'])?></span><span><strong><?=money((int)$due['payout_pence'])?></strong></span><span><?php if((int)$due['payout_pence']>0&&filter_var((string)$recipient['paypal_email'],FILTER_VALIDATE_EMAIL)):?><form method="post" data-no-async><input type="hidden" name="user_id" value="<?=$recipient['id']?>"><input type="hidden" name="period_start" value="<?=e($start)?>"><input type="hidden" name="period_end" value="<?=e($end)?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button tiny" onclick="return confirm('Mark this user payout as paid and email the user?')">Mark as paid</button></form><?php else:?><span class="muted">No payout</span><?php endif;?></span></div><?php endforeach;?></div></section><?php admin_payout_layout_end();
